coverage = cells('Coverage', 'C804:D813')
prov_areas = {}
for p, a in coverage:
    prov_areas.setdefault(p, set()).add(a)
required = values('Required', 'C42:C45')
req_set = set(required)

min_count = None
for r in range(1, len(provider_list) + 1):
    for combo in itertools.combinations(provider_list, r):
        covered = set()
        for p in combo:
            if p in prov_areas:
                covered.update(prov_areas[p])
        if req_set.issubset(covered):
            min_count = r
            break
    if min_count is not None:
        break
result = min_count

